script:
(function () {
  'use strict';
  // Savings needed to fund a future period of long-term care.
  //   n = years until care, Y = years of care, C = yearly cost today, g = care inflation,
  //   r = return while saving, rc = return during care.
  //   cost in care year k (k = 0..Y-1) = C x (1 + g)^(n + k), paid at the start of that year
  //   needed when care starts  F = sum of C x (1 + g)^(n + k) / (1 + rc)^k
  //   gap                      G = max(0, F - savings x (1 + r)^n)
  //   monthly saving M: end-of-month deposits at i = (1 + r)^(1/12) - 1, raised by the step-up
  //   each year; M = G / (future value of the deposit stream with M = 1)
  //   lump sum today           = G / (1 + r)^n
  // CHECKS (Node, scratch tests): $100,000 a year, 3 years, 0% inflation and 0% care return ->
  // F = $300,000; 3% inflation with rc = 3% in 20 years -> F = 3 x 100,000 x 1.03^20 =
  // $541,833.37; $300,000 gap in 20 years at 6% with no savings -> M = 300,000 x i /
  // ((1 + i)^240 - 1) = $661.61 a month, lump sum 300,000 / 1.06^20 = $93,541.42; the
  // year-by-year table ends at a $0 balance; savings already enough -> $0 needed; care starting
  // now -> lump sum only; 0% return -> M = G / (12 x n).
  // No tax or regulatory constants: costs, inflation and returns are the user's own inputs.

  // p: age, careAge, cost, years, inflation, saved, ret, careRet, stepUp (decimals)
  function plan(p) {
    var n = p.careAge - p.age, F = 0, total = 0;
    for (var k = 0; k < p.years; k++) {
      var c = p.cost * Math.pow(1 + p.inflation, n + k);
      total += c;
      F += c / Math.pow(1 + p.careRet, k);
    }
    var grown = p.saved * Math.pow(1 + p.ret, n), gap = Math.max(0, F - grown);
    var i = Math.pow(1 + p.ret, 1 / 12) - 1;
    function stream(M, rows) {
      var bal = p.saved, paidIn = 0;
      for (var y = 0; y < n; y++) {
        var dep = M * Math.pow(1 + p.stepUp, y), yIn = 0, yGrowth = 0;
        for (var m = 0; m < 12; m++) { var g = bal * i; bal += g + dep; yGrowth += g; yIn += dep; }
        paidIn += yIn;
        if (rows) rows.push({ age: p.age + y, saved: yIn, care: 0, growth: yGrowth, balance: bal });
      }
      return { bal: bal, paidIn: paidIn };
    }
    var unit = n > 0 ? stream(1).bal - grown : 0;
    var M = n > 0 && gap > 0 && unit > 0 ? gap / unit : 0;
    var rows = [], s = stream(M, rows), bal = n > 0 ? s.bal : p.saved + gap;
    for (var k2 = 0; k2 < p.years; k2++) {
      var cost = p.cost * Math.pow(1 + p.inflation, n + k2), pay = Math.min(cost, Math.max(0, bal));
      bal -= pay;
      var growth = k2 < p.years - 1 ? bal * p.careRet : 0;
      bal += growth;
      rows.push({ age: p.careAge + k2, saved: k2 === 0 && n === 0 ? gap : 0, care: pay, growth: growth, balance: bal });
    }
    return { n: n, F: F, total: total, first: p.cost * Math.pow(1 + p.inflation, n), grown: grown, gap: gap, M: M,
             lump: gap / Math.pow(1 + p.ret, n), paidIn: s.paidIn, rows: rows, surplus: Math.max(0, grown - F) };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var age = num('lrAge'), careAge = num('lrCareAge'), cost = num('lrCost'), years = num('lrYears'),
        inflation = num('lrInflation'), saved = num('lrSaved'), ret = num('lrReturn'), careRet = num('lrCareReturn'),
        stepUp = num('lrStepUp');
    var error = document.getElementById('lrError'), msg = '';
    if ([age, careAge, cost, years, inflation, saved, ret, careRet, stepUp].some(isNaN) || cost < 0 || saved < 0)
      msg = 'Enter non-negative amounts in every field.';
    else if ([age, careAge, years].some(function (v) { return Math.round(v) !== v; })) msg = 'Enter ages and years of care as whole numbers.';
    else if (age < 18 || age > 100) msg = 'Enter a current age from 18 to 100.';
    else if (careAge < age || careAge > 110) msg = 'The age care starts must be between your current age and 110.';
    else if (years < 1 || years > 30) msg = 'Enter 1 to 30 years of care.';
    else if (inflation < 0 || inflation > 15) msg = 'Enter care cost inflation from 0 to 15%.';
    else if (ret < 0 || ret > 20 || careRet < 0 || careRet > 20) msg = 'Enter returns from 0 to 20%.';
    else if (stepUp < 0 || stepUp > 20) msg = 'Enter a yearly increase from 0 to 20%.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var r = plan({ age: age, careAge: careAge, cost: cost, years: years, inflation: inflation / 100, saved: saved,
                   ret: ret / 100, careRet: careRet / 100, stepUp: stepUp / 100 });
    set('lrMonthlyLabel', stepUp > 0 && r.n > 0 ? 'Monthly saving needed this year' : 'Monthly saving needed');
    set('lrMonthly', r.n > 0 ? cents.format(r.M) : 'Care starts now');
    set('lrLump', money(r.lump));
    set('lrFundLabel', 'Needed at age ' + careAge);
    set('lrFund', money(r.F));
    set('lrFirst', money(r.first));
    set('lrTotal', money(r.total));
    set('lrGrown', money(r.grown));
    set('lrGap', money(r.gap));
    set('lrPaidIn', money(r.paidIn));
    set('lrSummary', r.n > 0 && r.gap > 0
      ? 'Saving ' + cents.format(r.M) + ' a month' + (stepUp > 0 ? ', raised ' + stepUp + '% each year,' : '') + ' for ' + r.n +
        ' years builds the ' + money(r.F) + ' needed at age ' + careAge + ' to pay ' + years + ' year' + (years === 1 ? '' : 's') +
        ' of care costing ' + money(r.total) + ' in total.'
      : 'The table shows your savings paying each year\'s care cost.');
    var cov = document.getElementById('lrCovered');
    cov.hidden = !(r.gap <= 0);
    if (r.gap <= 0) cov.textContent = 'Your current savings already cover the projected cost, with about ' + money(r.surplus) +
        ' to spare at age ' + careAge + ' if the returns hold.';
    var body = document.getElementById('lrSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money(row.saved), money(row.care), money(row.growth), money(row.balance)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('lrForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
